<template>
  <q-card flat bordered class="agent-issue-history-card">
    <q-card-section>
      <q-list v-if="tasks.length" separator dense>
        <q-item
          v-for="task in tasks"
          :key="task.id"
          clickable
          @click="$router.push('/doc-net/issues/' + task.id)"
          class="history-item"
        >
          <q-item-section side>
            <PriorityIcon :priority="task.priority" size="sm" />
          </q-item-section>
          <q-item-section>
            <q-item-label class="history-title ellipsis">{{ task.title }}</q-item-label>
            <q-item-label caption class="row items-center q-gutter-xs">
              <StatusBadge :status="task.status" size="sm" />
              <span v-if="getRunDuration(task.id)" class="text-grey-6">
                <q-icon name="timer" size="12px" class="q-mr-xs" />{{ getRunDuration(task.id) }}
              </span>
              <span v-if="getRunTokens(task.id)" class="text-grey-6">
                <q-icon name="token" size="12px" class="q-mr-xs" />{{ getRunTokens(task.id) }}
              </span>
            </q-item-label>
          </q-item-section>
          <q-item-section side class="text-caption text-grey-6">
            {{ formatDate(task.last_modified_on) }}
          </q-item-section>
        </q-item>
      </q-list>

      <div v-else class="text-center q-pa-md">
        <q-icon name="history" size="32px" color="grey-5" />
        <div class="text-caption text-grey-6 q-mt-xs">{{ $t('no_issue_history') }}</div>
      </div>
    </q-card-section>
  </q-card>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import type { DocNetIssue } from 'src/@types/docnet';
import StatusBadge from '../../shared/StatusBadge.vue';
import PriorityIcon from '../../shared/PriorityIcon.vue';
import { formatRelativeTime } from 'src/utils/docnet/formatting';

export default defineComponent({
  name: 'AgentIssueHistory',

  components: {
    StatusBadge,
    PriorityIcon,
  },

  props: {
    tasks: {
      type: Array as PropType<DocNetIssue[]>,
      required: true,
    },
    runs: {
      type: Array as PropType<any[]>,
      default: () => [],
    },
  },

  computed: {
    runsByIssue(): Record<string, any> {
      const map: Record<string, any> = {};
      for (const run of this.runs) {
        const issueId = run.issue_id || run.issueId;
        if (issueId) map[String(issueId)] = run;
      }
      return map;
    },
  },

  methods: {
    getRunDuration(issueId: string): string {
      const run = this.runsByIssue[issueId];
      if (!run) return '';
      const ms = run.duration_ms || (run.duration_seconds ? run.duration_seconds * 1000 : 0);
      if (!ms) return '';
      const secs = Math.round(ms / 1000);
      return secs < 60 ? `${secs}s` : `${Math.floor(secs / 60)}m ${secs % 60}s`;
    },

    getRunTokens(issueId: string): string {
      const run = this.runsByIssue[issueId];
      if (!run?.token_usage) return '';
      const total = run.token_usage.billed ?? 0;
      if (!total) return '';
      return total.toLocaleString();
    },

    formatDate(isoDate: string): string {
      return formatRelativeTime(isoDate, this.$t);
    },
  },
});
</script>

