<template>
  <div class="agent-memory-list">
    <!-- Empty state -->
    <div v-if="loading && !items.length" class="text-center q-pa-md">
      <q-spinner-dots color="primary" size="32px" />
    </div>

    <div v-else-if="!loading && !items.length" class="memory-empty">
      <q-icon name="auto_awesome" size="32px" color="grey-5" />
      <div class="text-caption text-grey-6 q-mt-xs">
        {{ $t('agent_memory_empty') || 'No lessons learned yet.' }}
      </div>
    </div>

    <!-- Stats summary -->
    <div v-if="stats && items.length" class="memory-stats q-mb-sm">
      <span class="memory-stat-chip">
        <q-icon name="psychology" size="16px" class="q-mr-xs" />
        {{ stats.total }} {{ $t('agent_memory_lessons') || 'lessons' }}
      </span>
      <span class="memory-stat-chip">
        <q-icon name="repeat" size="16px" class="q-mr-xs" />
        {{ stats.total_applied }} {{ $t('agent_memory_applied') || 'times applied' }}
      </span>
      <span v-if="stats.helpful" class="memory-stat-chip memory-stat-chip--positive">
        <q-icon name="thumb_up" size="16px" class="q-mr-xs" />
        {{ stats.helpful }}
      </span>
      <span v-if="stats.unhelpful" class="memory-stat-chip memory-stat-chip--negative">
        <q-icon name="thumb_down" size="16px" class="q-mr-xs" />
        {{ stats.unhelpful }}
      </span>
    </div>

    <!-- Source filter -->
    <q-btn-toggle
      v-if="items.length || sourceFilter !== null"
      v-model="sourceFilterValue"
      :options="sourceFilterOptions"
      dense
      no-caps
      rounded
      unelevated
      size="sm"
      toggle-color="primary"
      color="white"
      text-color="primary"
      class="q-mb-sm"
      @update:model-value="onFilterChange"
    />

    <!-- Memory rows -->
    <q-list separator dense>
      <q-item
        v-for="m in items"
        :key="m.id"
        class="memory-item"
      >
        <q-item-section>
          <q-item-label class="memory-content">{{ m.content }}</q-item-label>
          <q-item-label caption>
            <span :class="['memory-source-chip', `memory-source-chip--${m.source}`]">
              {{ sourceLabel(m.source) }}
            </span>
            <span class="memory-meta-sep">·</span>
            <span class="memory-meta">{{ Math.round(m.confidence * 100) }}% {{ $t('docnet_confidence') }}</span>
            <span class="memory-meta-sep">·</span>
            <span class="memory-meta">
              {{ m.usage_count }} {{ $t('agent_memory_uses') || 'uses' }}
            </span>
            <template v-if="m.tags && m.tags.length">
              <span class="memory-meta-sep">·</span>
              <span v-for="t in m.tags" :key="t" class="memory-tag">{{ t }}</span>
            </template>
          </q-item-label>
        </q-item-section>

        <q-item-section side>
          <div class="memory-actions">
            <q-btn
              flat
              round
              dense
              size="sm"
              icon="thumb_up"
              :color="m.helpful_count > 0 ? 'positive' : 'grey-6'"
              :disable="busy[m.id]"
              :title="$t('mark_helpful') || 'Mark helpful'"
              @click="vote(m, 'helpful')"
            >
              <span v-if="m.helpful_count" class="memory-vote-count">{{ m.helpful_count }}</span>
            </q-btn>
            <q-btn
              flat
              round
              dense
              size="sm"
              icon="thumb_down"
              :color="m.unhelpful_count > 0 ? 'negative' : 'grey-6'"
              :disable="busy[m.id]"
              :title="$t('mark_unhelpful') || 'Mark not helpful'"
              @click="vote(m, 'unhelpful')"
            >
              <span v-if="m.unhelpful_count" class="memory-vote-count">{{ m.unhelpful_count }}</span>
            </q-btn>
            <q-btn
              flat
              round
              dense
              size="sm"
              icon="delete_outline"
              color="grey-6"
              :disable="busy[m.id]"
              :title="$t('delete') || 'Delete'"
              @click="onDelete(m)"
            />
          </div>
        </q-item-section>
      </q-item>
    </q-list>

    <div v-if="total > items.length" class="text-center q-mt-sm">
      <q-btn
        flat
        dense
        no-caps
        :label="$t('load_more') || 'Load more'"
        @click="loadMore"
      />
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, getCurrentInstance, ref, watch, type PropType } from 'vue';
import { notify } from 'src/components/notifications/notify';
import DocNetAgentMemoryService, {
  type AgentMemory,
  type AgentMemoryStats,
  type AgentMemorySource,
} from 'src/services/docnet/DocNetAgentMemoryService';

type SourceFilter = AgentMemorySource | null;

export default defineComponent({
  name: 'AgentMemoryList',
  props: {
    agentId: {
      type: String as PropType<string | null>,
      required: false,
      default: null,
    },
    pageSize: {
      type: Number,
      default: 25,
    },
  },
  setup(props) {
    const globals = getCurrentInstance()?.appContext.config.globalProperties;
    const t = (key: string): string => (globals?.$t ? (globals.$t(key) as string) : key);
    const service = new DocNetAgentMemoryService();
    const items = ref<AgentMemory[]>([]);
    const total = ref(0);
    const stats = ref<AgentMemoryStats | null>(null);
    const loading = ref(false);
    const busy = ref<Record<string, boolean>>({});
    const sourceFilter = ref<SourceFilter>(null);
    const sourceFilterValue = ref<SourceFilter>(null);

    const sourceFilterOptions = [
      { label: t('docnet_all'), value: null },
      { label: t('docnet_memory_source_user_feedback'), value: 'user_feedback' },
      { label: t('docnet_memory_source_self_reflection'), value: 'self_reflection' },
    ];

    async function reload(offset = 0) {
      loading.value = true;
      try {
        const list = await service.list({
          agent_id: props.agentId,
          source: sourceFilter.value,
          limit: props.pageSize,
          offset,
        });
        if (offset === 0) {
          items.value = list.items;
        } else {
          items.value = [...items.value, ...list.items];
        }
        total.value = list.total;
        stats.value = await service.stats(props.agentId);
      } catch (err) {
        // Surface the error but keep the UI usable — memory is a
        // secondary panel, not the agent's primary action surface.
        // eslint-disable-next-line no-console
        console.warn('AgentMemoryList: failed to load', err);
        notify.error(t('docnet_memory_load_failed'));
      } finally {
        loading.value = false;
      }
    }

    async function loadMore() {
      await reload(items.value.length);
    }

    async function vote(memory: AgentMemory, verdict: 'helpful' | 'unhelpful') {
      busy.value[memory.id] = true;
      try {
        const updated = await service.feedback(memory.id, verdict);
        const idx = items.value.findIndex((m) => m.id === memory.id);
        if (idx >= 0) {
          items.value[idx] = updated;
        }
        stats.value = await service.stats(props.agentId);
      } catch (err) {
        notify.error(t('docnet_feedback_save_failed'));
      } finally {
        // Delete the key rather than setting it to false — over a long
        // admin session voting on many memories, leaving stale `false`
        // entries grows `busy` unboundedly.
        delete busy.value[memory.id];
      }
    }

    async function onDelete(memory: AgentMemory) {
      busy.value[memory.id] = true;
      try {
        await service.remove(memory.id);
        items.value = items.value.filter((m) => m.id !== memory.id);
        total.value = Math.max(0, total.value - 1);
        stats.value = await service.stats(props.agentId);
        notify.success(t('docnet_memory_deleted'));
      } catch (err) {
        notify.error(t('docnet_memory_delete_failed'));
      } finally {
        delete busy.value[memory.id];
      }
    }

    function sourceLabel(s: AgentMemorySource): string {
      switch (s) {
        case 'user_feedback':
          return t('docnet_memory_source_user_feedback');
        case 'self_reflection':
          return t('docnet_memory_source_self_reflection');
        case 'episodic':
          return t('docnet_memory_source_episodic');
        default:
          return s;
      }
    }

    function onFilterChange(v: SourceFilter) {
      sourceFilter.value = v;
      reload(0);
    }

    watch(
      () => props.agentId,
      () => reload(0),
      { immediate: true },
    );

    return {
      items,
      total,
      stats,
      loading,
      busy,
      sourceFilter,
      sourceFilterValue,
      sourceFilterOptions,
      reload,
      loadMore,
      vote,
      onDelete,
      sourceLabel,
      onFilterChange,
    };
  },
});
</script>

