        <div class="col-12 col-sm-6 col-md-4">
          <div class="stat-card">
            <div class="stat-card-title">{{ $t('docnet_orchestrator_activity') }}</div>
            <div class="stat-card-subtitle">{{ $t('docnet_last_14_days') }}</div>
            <div class="mini-chart">
              <div
                v-for="(val, i) in orchestratorActivityData"
                :key="i"
                class="mini-bar"
                :style="{ height: (val * 0.8) + 'px' }"
                :class="{ 'bar-today': i === orchestratorActivityData.length - 1 }"
                style="background: #ab47bc"
              />
