            <div class="stat-card-value">{{ totalOrchestratorRuns }} {{ $t('docnet_runs') }}</div>
          </div>
        </div>

        <!-- Missions by Status -->
        <div class="col-12 col-sm-6 col-md-4">
          <div class="stat-card">
            <div class="stat-card-title">{{ $t('missions_by_status') }}</div>
            <div class="stat-card-subtitle">{{ $t('current_distribution') }}</div>
