                <q-space />
                <span class="status-dot-count">{{ s.count }}</span>
              </div>
            </div>
          </div>
        </div>
      </div>

      <!-- Stats Cards Row (regular agents) -->
      <div v-if="!isOrchestrator" class="row q-gutter-md q-mb-lg stats-row">
