            <div class="stat-card-subtitle">{{ $t('last_14_days') }}</div>
            <div class="mini-chart">
              <div
                v-for="(val, i) in runActivityData"
                :key="i"
                class="mini-bar"
                :style="{ height: (val * 0.8) + 'px' }"
                :class="{ 'bar-today': i === runActivityData.length - 1 }"
              />
