              <div v-for="s in statusData" :key="s.label" class="status-dot-row">
                <span class="status-dot" :style="{ background: s.color }" />
                <span class="status-dot-label">{{ s.label }}</span>
                <q-space />
                <span class="status-dot-count">{{ s.count }}</span>
              </div>
            </div>
          </div>
        </div>
      </div>

