              <f-btn
                appearance="flat"
                :label="$t('cancel')"
                size="sm"
                @click="editingPrompt = false; promptDraft = profile.agent.system_prompt || ''"
              />
              <f-btn
                appearance="primary"
                :label="$t('save')"
