                size="sm"
                :loading="savingPrompt"
                @click="savePrompt"
              />
            </template>
            <f-btn
              v-if="!profile.agent.is_system && !editingPrompt && showDefaultPrompt"
              appearance="flat"
              icon="edit"
              :label="$t('edit')"
              size="sm"
              @click="editingPrompt = true; promptDraft = profile.agent.system_prompt || ''"
            />
            <f-btn
              appearance="flat"
              :icon="showDefaultPrompt ? 'expand_less' : 'expand_more'"
              :label="showDefaultPrompt ? $t('hide') : $t('show')"
              size="sm"
              @click="showDefaultPrompt = !showDefaultPrompt"
            />
          </div>
        </div>
        <template v-if="showDefaultPrompt">
          <q-input
            v-if="editingPrompt && !profile.agent.is_system"
            v-model="promptDraft"
            type="textarea"
            outlined
            dense
            autogrow
            :input-style="{ minHeight: '200px', fontFamily: 'monospace', fontSize: '13px' }"
          />
          <div v-else class="prompt-display prompt-display--readonly markdown-body" v-html="renderMarkdown(profile.agent.system_prompt || '—')" />
        </template>
      </div>

      <!-- Model Settings -->
      <div class="section-block q-mb-lg">
