               agents: it only dials reasoning depth ↔ cost (can't change the
               model, prompt, or tools), so it's safe to expose. The backend
               permits config updates on system agents. -->
          <div>
            <div class="text-caption text-grey-6 q-mb-xs">{{ $t('reasoning_effort') }}</div>
            <q-select
              :model-value="profile.agent.config?.reasoning_effort || 'medium'"
              :options="effortOptions"
              outlined
              dense
              emit-value
              map-options
              @update:model-value="updateReasoningEffort($event)"
            >
              <template v-slot:option="scope">
                <q-item v-bind="scope.itemProps">
                  <q-item-section>
                    <q-item-label>{{ scope.opt.label }}</q-item-label>
                    <q-item-label caption>{{ scope.opt.description }}</q-item-label>
                  </q-item-section>
                </q-item>
              </template>
            </q-select>
            <div class="text-caption text-grey-6 q-mt-xs">
              {{ $t('reasoning_effort_hint') }}
            </div>
          </div>
        </div>
      </div>

      <!-- Custom Instructions -->
      <div class="section-block q-mb-lg">
        <div class="section-header">
          <span class="section-title">{{ $t('custom_instructions') }}</span>
          <f-btn
            appearance="flat"
            :icon="showCustomInstructions ? 'expand_less' : 'expand_more'"
            :label="showCustomInstructions ? $t('hide') : $t('show')"
            size="sm"
            @click="showCustomInstructions = !showCustomInstructions"
          />
        </div>
        <div v-if="showCustomInstructions">
