              <q-btn
                v-for="p in personalityOptions"
                :key="p.key"
                :outline="selectedPersonality !== p.key"
                :color="selectedPersonality === p.key ? 'primary' : 'grey-7'"
                :loading="savingPersonality === p.key"
                no-caps
                dense
                round
                class="personality-btn"
                @click="togglePersonality(p.key)"
              >
                <img v-if="p.logo" :src="p.logo as string" :alt="$t(p.translationKey)" class="personality-logo" :class="{ 'personality-logo--selected': selectedPersonality === p.key }" />
                <span v-else class="personality-icon">{{ p.icon }}</span>
                <q-tooltip>{{ $t(p.translationKey) }}</q-tooltip>
              </q-btn>
            </div>
          </div>

