                     fallthrough) and ``blocked`` (its own prop), but
                     only ``blocked`` triggers the ``f-btn--blocked``
                     wrapper class that carries ``cursor:
                     not-allowed``.  Use ``blocked`` so disabled
                     buttons honestly signal disabled-state on hover —
                     otherwise the cursor stays default and the
                     button looks broken rather than gated. -->
                <f-btn
                  appearance="flat"
                  :label="$t('clear')"
                  icon="delete_outline"
                  size="sm"
                  :blocked="isClearNoop || savingInstructions"
                  @click="instructionsDraft = ''"
                />
                <f-btn
                  appearance="flat"
                  :label="$t('cancel')"
                  icon="close"
                  size="sm"
                  :blocked="savingInstructions"
                  @click="cancelEditInstructions"
                />
                <f-btn
                  appearance="primary"
                  :label="$t('save')"
                  icon="save"
                  size="sm"
                  :loading="savingInstructions"
                  :blocked="!instructionsChanged"
                  @click="saveInstructions"
                />
              </template>
              <f-btn
                v-else
                appearance="flat"
                :label="customInstructions ? $t('edit') : $t('add')"
                :icon="customInstructions ? 'edit' : 'add'"
                size="sm"
                @click="startEditInstructions"
              />
            </div>
          </div>
          <template v-if="!editingInstructions">
