                 system agent's base default rather than this org's
                 overlay.  Muted styling on the body reinforces that
                 it's not the org's own text — saving it back without
                 changes would freeze the org on the current default
                 even if we improve it later, so we prompt them to
                 explicitly customise. -->
            <div
              v-if="loadedIsDefault"
              class="row items-center q-gutter-xs q-mb-xs text-caption text-grey-7"
            >
              <q-icon name="link" size="14px" />
              <span>{{ $t('default') }}</span>
            </div>
            <div
              v-if="customInstructions"
              class="prompt-display markdown-body"
              :class="{ 'prompt-display--inherited': loadedIsDefault }"
              v-html="renderMarkdown(customInstructions)"
            />
