          <q-input
            v-else
            v-model="instructionsDraft"
            type="textarea"
            outlined
            autogrow
            :rows="6"
            :placeholder="$t('custom_instructions_placeholder')"
            class="prompt-editor"
          />
        </div>
      </div>

