           the same dialog used for tool selection / per-tool
           policy. -->
      <div class="section-block q-mb-lg">
        <div class="section-header">
          <span class="section-title">{{ $t('skills') || 'Skills' }}</span>
          <div class="row items-center q-gutter-xs">
            <span class="text-caption text-grey-6">
              {{ skillCardsForProfile.length }}
              {{ $t('skills') || 'Skills' }}
            </span>
