                :title="isToolEffectivelyCritical(tool) ? $t('tool_requires_approval') : ''"
                class="profile-skill-card__chip"
              >
                {{ formatToolName(tool) }}
              </q-chip>
            </q-card-section>
          </q-card>
        </div>
        <div
          v-else
          class="text-grey-6 text-center q-pa-sm"
        >
          {{ $t('no_skills_configured') || 'No skills configured' }}
        </div>
      </div>

      <!-- Agent Pool (orchestrator only) -->
