    </q-dialog>

    <!-- Tools Editor -->
    <q-dialog v-model="showMcpEditor" persistent>
      <q-card style="min-width: min(700px, 90vw); max-width: 900px; max-height: 90vh;">
        <q-card-section class="row items-center q-pb-none">
          <div class="text-h6">{{ $t('skills') || 'Skills' }}</div>
          <q-space />
          <q-btn flat round dense icon="close" @click="showMcpEditor = false" />
        </q-card-section>
        <q-card-section style="max-height: 60vh; overflow-y: auto;">
          <!-- For system agents we pass the real ``agentId`` so the
               ``ToolApprovalToggle`` persists per-tool overrides
               immediately to ``agent_org_settings`` via the
               dedicated endpoint — no Save round-trip, no risk of
               the parent's PUT-everything ``saveMcpTools`` writing
               to the shared system row (which the backend would
               403 anyway).  Custom agents keep ``agentId=null`` so
               their changes buffer through ``localOverrides`` and
               persist together with the tool selection on Save. -->
          <McpToolSelector
            v-model="mcpEditorValue"
            :skills="profile?.agent.skills || []"
            :available-skills="agentsSettingsStore.availableSkills"
            :disabled-tools="disabledToolsValue"
            :mcp-tools="mcpToolsValue"
            :agent-id="profile?.agent.is_system ? profile.agent.id : null"
            :approval-mode="effectiveApprovalMode"
            :local-overrides="profile?.agent.is_system ? null : toolApprovalsValue"
            :read-only-selection="!!profile?.agent.is_system"
            @update:disabled-tools="disabledToolsValue = $event"
            @update:mcp-tools="mcpToolsValue = $event"
            @update:local-overrides="toolApprovalsValue = $event"
          />
        </q-card-section>
        <q-card-actions align="right" class="q-pa-md">
          <!-- System agents: per-tool approval toggles persist
               immediately through their own endpoint, so no Save
               here.  Custom agents: keep the buffered Cancel/Save
               flow — the dialog edits a draft and commits on Save. -->
          <template v-if="profile?.agent.is_system">
            <q-btn unelevated color="primary" :label="$t('done')" no-caps @click="showMcpEditor = false" />
          </template>
          <template v-else>
            <q-btn flat :label="$t('cancel')" no-caps @click="showMcpEditor = false" />
            <q-btn unelevated color="primary" :label="$t('save')" no-caps :loading="savingMcpTools" @click="saveMcpTools" />
          </template>
        </q-card-actions>
      </q-card>
    </q-dialog>

    <!-- Delete Confirmation -->
    <q-dialog v-model="showDeleteConfirm">
      <q-card style="min-width: 350px">
        <q-card-section>
          <div class="text-h6">{{ $t('delete_agent_title') }}</div>
        </q-card-section>
        <q-card-section class="q-pt-none">
          {{ $t('delete_agent_confirm', { name: profile?.agent.name }) }}
        </q-card-section>
        <q-card-actions align="right">
          <q-btn flat :label="$t('cancel')" v-close-popup />
          <q-btn color="negative" :label="$t('delete')" :loading="deleting" @click="deleteAgent" />
        </q-card-actions>
      </q-card>
    </q-dialog>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, defineAsyncComponent } from 'vue';
import { useRouter } from 'vue-router';
import { useDocNetAgentStore } from 'src/store/DocNet/docnet-agents.store';
import { useDocNetIssueStore } from 'src/store/DocNet/docnet-issues.store';
import { useDocNetMissionStore } from 'src/store/DocNet/docnet-missions.store';
import { useDocNetWebSocketStore } from 'src/store/DocNet/docnet-websocket.store';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { storeToRefs } from 'pinia';
import type { DocNetAgentProfile, DocNetIssue, DocNetMission } from 'src/@types/docnet';
import AgentIssueHistory from './components/AgentIssueHistory.vue';
import AgentMemoryList from './components/AgentMemoryList.vue';
import AgentWizard from 'src/pages/Settings/Components/Agents/AgentWizard.vue';
import StatusBadge from '../shared/StatusBadge.vue';
import { statusLabel } from '../shared/docnet-labels';
import AgentApiService from 'src/services/settings/AgentApiService';
import { renderMarkdown } from 'src/utils/markdown';
import { formatToolName, hasMcpConfig as checkMcpConfig, agentToolCount as countAgentTools, formatRelativeTime } from 'src/utils/docnet/formatting';
import { useAgentsStore } from 'src/store/Settings/agents.store';

const agentApiService = new AgentApiService();

export default defineComponent({
  name: 'DocNetAgentProfile',

  components: {
    AgentIssueHistory,
    AgentMemoryList,
    AgentWizard,
    StatusBadge,
    McpToolSelector: defineAsyncComponent(() => import('src/pages/Settings/Components/Agents/McpToolSelector.vue')),
  },

  setup() {
    const agentStore = useDocNetAgentStore();
    const taskStore = useDocNetIssueStore();
    const missionStore = useDocNetMissionStore();
    const { currentProfile: profile, loading, profiles, agentRuns } = storeToRefs(agentStore);
    const { issues: allTasks } = storeToRefs(taskStore);
    const { missions } = storeToRefs(missionStore);
    const router = useRouter();
    const agentsSettingsStore = useAgentsStore();
    return { router, agentStore, taskStore, missionStore, profile, loading, profiles, allTasks, agentRuns, missions, agentsSettingsStore };
  },

  data() {
    return {
      toggleLoading: false,
      savingApproval: false,
      showDefaultPrompt: false,
      showModelSettings: false,
      editingPrompt: false,
      promptDraft: '',
      savingPrompt: false,
      showCustomInstructions: false,
      editingInstructions: false,
      instructionsDraft: '',
      savingInstructions: false,
      loadedCustomInstructions: '',
      // True when ``loadedCustomInstructions`` is the inherited base
      // default from the system agent's ``config`` rather than the
      // org's own overlay.  Drives the "inherited" badge + muted
      // styling so admins don't mistake the inherited text for
      // their own and accidentally freeze themselves on the default
      // by saving without changes.
      loadedIsDefault: false,
      showEditWizard: false,
      showDeleteConfirm: false,
      showMcpEditor: false,
      mcpEditorValue: {} as Record<string, string[]>,
      disabledToolsValue: [] as string[],
      mcpToolsValue: [] as string[],
      // Buffered per-tool approval overrides for the tools-edit
      // dialog.  Seeded from agent.config.tool_approvals on open,
      // mutated as the user clicks settings cogs, and persisted
      // alongside the rest of the dialog state when "Save" fires.
      toolApprovalsValue: {} as Record<string, boolean>,
      savingMcpTools: false,
      deleting: false,
      selectedPersonality: null as string | null,
      savingPersonality: null as string | null,
      personalityOptions: [
        { key: 'docbits', icon: '', logo: '/icons/LOGO.svg', translationKey: 'personality_docbits' },
        { key: 'bavarian', icon: '🥨', translationKey: 'personality_bavarian' },
        { key: 'cowboy', icon: '🤠', translationKey: 'personality_cowboy' },
        { key: 'drunk', icon: '🍺', translationKey: 'personality_drunk' },
      ],
    };
  },

  computed: {
    effortOptions(): Array<{ value: string; label: string; description: string }> {
      return [
        { value: 'none', label: this.$t('effort_none_label') as string, description: this.$t('effort_none_desc') as string },
        { value: 'low', label: this.$t('effort_low_label') as string, description: this.$t('effort_low_desc') as string },
        { value: 'medium', label: this.$t('effort_medium_label') as string, description: this.$t('effort_medium_desc') as string },
        { value: 'high', label: this.$t('effort_high_label') as string, description: this.$t('effort_high_desc') as string },
        { value: 'xhigh', label: this.$t('effort_xhigh_label') as string, description: this.$t('effort_xhigh_desc') as string },
      ];
    },

    effectiveApprovalMode(): string {
      return this.profile?.approval_mode
        || this.profile?.agent?.config?.approval_mode
        || 'critical';
    },

    approvalModeOptions() {
      return [
        { label: this.$t('approval_none'), value: 'none' },
        { label: this.$t('approval_critical'), value: 'critical' },
        { label: this.$t('approval_all'), value: 'all' },
      ];
    },

    isOrchestrator(): boolean {
      return this.profile?.role === 'orchestrator'
        || this.profile?.agent?.id === 'docbits-orchestrator'
        || this.profile?.agent?.name === 'DocBits Orchestrator';
    },

    hasMcpConfig(): boolean {
      return checkMcpConfig(this.profile?.agent || null);
    },
    mcpToolCount(): number {
      // Kept named `mcpToolCount` for template/test stability, but now
      // counts every tool on the agent (native + MCP). Pre-fix the
      // header showed 0 for agents that only had native tools.
      return countAgentTools(this.profile?.agent || null);
    },

    /** Read-only skill cards for the profile.  Groups the agent's
     *  selected tools by skill — hides skills with zero selected
     *  tools, and appends a single locked card for the
     *  always-available primitives (``request_human_approval``)
     *  so the user sees the full picture of what the agent can do. */
    skillCardsForProfile(): Array<{
      id: string;
      label: string;
      description?: string;
      tools: string[];
      locked: boolean;
    }> {
      if (!this.profile) return [];
      const ALWAYS_INCLUDED = new Set(['request_human_approval']);
      const selected = new Set(this.profile.agent.tools || []);
      const out: Array<{
        id: string;
        label: string;
        description?: string;
        tools: string[];
        locked: boolean;
      }> = [];
      const seen = new Set<string>();

      for (const def of this.agentsSettingsStore.availableSkills || []) {
        const skillTools = def.tools || [];
        const hits = skillTools.filter(
          (t: string) => selected.has(t) && !seen.has(t),
        );
        if (!hits.length) continue;
        for (const t of hits) seen.add(t);
        out.push({
          id: def.id,
          label: def.name || def.id,
          description: def.description,
          tools: hits,
          locked: false,
        });
      }

      // Always-available primitives — render even when no other
      // skill is selected so the profile is honest about what the
      // agent can do.
      const alwaysHits: string[] = [];
      for (const name of ALWAYS_INCLUDED) {
        if (seen.has(name)) continue;
        alwaysHits.push(name);
        seen.add(name);
      }
      if (alwaysHits.length) {
        // ``$t`` returns the key itself when missing, so a ``||``
        // fallback never kicks in.  Use ``$te`` (translation-
        // exists) to decide whether to call ``$t`` or fall back
        // to a literal English string.  Description omitted —
        // the "Always Available" label + lock icon already
        // convey "can't be disabled".
        const labelKey = 'always_available_skill';
        out.push({
          id: '_always',
          label: this.$te(labelKey)
            ? (this.$t(labelKey) as string)
            : 'Always Available',
          tools: alwaysHits,
          locked: true,
        });
      }

      return out;
    },

    isLastEnabledOrchestrator(): boolean {
      if (!this.profile || !this.isOrchestrator || this.profile.agent.is_enabled === false) return false;
      const enabledOrchCount = this.profiles.filter(
        (p) => p.role === 'orchestrator' && p.agent.is_enabled !== false,
      ).length;
      return enabledOrchCount <= 1;
    },

    poolAgents(): DocNetAgentProfile[] {
      if (!this.profile) return [];
      const excludeRoles = new Set(['orchestrator', 'router']);
      const excludeIds = new Set(['system-router', this.profile.agent.id]);
      return this.profiles.filter((p) =>
        p.agent.is_enabled !== false && !excludeRoles.has(p.role) && !excludeIds.has(p.agent.id)
      );
    },

    assignedAgentCount(): number {
      if (!this.profile) return 0;
      const orchId = this.profile.agent.id;
      return this.poolAgents.filter((p) => {
        const rt = p.reports_to;
        if (Array.isArray(rt)) return rt.includes(orchId);
        return rt === orchId;
      }).length;
    },

    isActive(): boolean {
      const hs = this.profile?.heartbeat_status;
      return hs === 'working' || hs === 'awake' || (this.profile?.workload_percent ?? 0) > 0;
    },

    customInstructions(): string {
      return this.loadedCustomInstructions;
    },

    instructionsChanged(): boolean {
      // Save button stays disabled when the draft equals what's
      // already loaded.  For an inherited default that means
      // "saving an exact copy of the inherited text" is impossible
      // — the only way to enable Save is to actually edit something,
      // which prevents the freeze-on-default trap (admin clicks
      // Save without changes and locks the org onto the current
      // default forever).  An empty draft is also "no change" when
      // already empty, so this works for the custom-agent case too.
      return this.instructionsDraft !== this.customInstructions;
    },

    /** Disable the Clear button when clearing would be a pure no-op:
     *  the draft is already empty, OR the agent is in inherited
     *  state and the draft hasn't been touched (clearing would
     *  round-trip through "save empty → backend falls back to the
     *  same inherited default" — two clicks for nothing).  Once
     *  the user types over the inherited text the draft no longer
     *  matches and Clear re-enables, which is correct: clearing is
     *  the path back to "I want to keep inheriting" after they
     *  changed their mind. */
    isClearNoop(): boolean {
      if (!this.instructionsDraft.trim()) return true;
      return (
        this.loadedIsDefault
        && this.instructionsDraft === this.customInstructions
      );
    },

    recentMissions(): DocNetMission[] {
      if (!this.profile) return [];
      const agentName = this.profile.agent.name;
      return [...this.missions]
        .filter((m) => m.agents_used?.includes(agentName))
        .sort((a, b) => new Date(b.created_on).getTime() - new Date(a.created_on).getTime())
        .slice(0, 10);
    },

    agentTasks(): DocNetIssue[] {
      if (!this.profile) return [];
      const agentId = this.profile.agent.id;
      return this.allTasks.filter((t) => t.assignee_id === agentId);
    },

    latestRun(): any | null {
      if (!this.agentRuns.length) return null;
      return this.agentRuns[0];
    },

    totalRuns(): number {
      return this.agentRuns.length;
    },

    runActivityData(): number[] {
      const days = 14;
      const buckets = new Array(days).fill(0);
      const now = Date.now();
      for (const run of this.agentRuns) {
        const d = new Date(run.created_on || run.started_at || run.created_at).getTime();
        if (isNaN(d)) continue;
        const daysAgo = Math.floor((now - d) / 86400000);
        if (daysAgo >= 0 && daysAgo < days) {
          buckets[days - 1 - daysAgo]++;
        }
      }
      const max = Math.max(...buckets, 1);
      return buckets.map((v) => Math.round((v / max) * 100));
    },

    successRateData(): number[] {
      const days = 14;
      const successBuckets = new Array(days).fill(0);
      const totalBuckets = new Array(days).fill(0);
      const now = Date.now();
      for (const run of this.agentRuns) {
        const d = new Date(run.created_at).getTime();
        const daysAgo = Math.floor((now - d) / 86400000);
        if (daysAgo >= 0 && daysAgo < days) {
          const idx = days - 1 - daysAgo;
          totalBuckets[idx]++;
          if (run.status === 'completed' || run.status === 'success') {
            successBuckets[idx]++;
          }
        }
      }
      return totalBuckets.map((total, i) =>
        total > 0 ? Math.round((successBuckets[i] / total) * 100) : 0,
      );
    },

    avgSuccessRate(): number {
      const completed = this.agentRuns.filter(
        (r: any) => r.status === 'completed' || r.status === 'success',
      ).length;
      return this.agentRuns.length
        ? Math.round((completed / this.agentRuns.length) * 100)
        : 0;
    },

    priorityData(): { label: string; count: number; percent: number; color: string }[] {
      const counts: Record<string, number> = { critical: 0, high: 0, medium: 0, low: 0 };
      for (const t of this.agentTasks) {
        const p = (t.priority || 'medium').toLowerCase();
        if (p in counts) counts[p]++;
      }
      const max = Math.max(...Object.values(counts), 1);
      const colors: Record<string, string> = {
        critical: '#e53935',
        high: '#ff9800',
        medium: '#2196f3',
        low: '#66bb6a',
      };
      return Object.entries(counts).map(([label, count]) => ({
        label: label.charAt(0).toUpperCase() + label.slice(1),
        count,
        percent: Math.round((count / max) * 100),
        color: colors[label],
      }));
    },

    /** Missions belonging to this agent (filtered by agents_used). */
    agentMissions(): DocNetMission[] {
      if (!this.profile) return [];
      const agentName = this.profile.agent.name;
      return this.missions.filter((m) => m.agents_used?.includes(agentName));
    },

    orchestratorActivityData(): number[] {
      const days = 14;
      const buckets = new Array(days).fill(0);
      const now = Date.now();
      for (const mission of this.agentMissions) {
        const d = new Date(mission.created_on).getTime();
        if (isNaN(d)) continue;
        const daysAgo = Math.floor((now - d) / 86400000);
        if (daysAgo >= 0 && daysAgo < days) {
          buckets[days - 1 - daysAgo]++;
        }
      }
      for (const run of this.agentRuns) {
        const d = new Date(run.created_on || run.started_at || run.created_at).getTime();
        if (isNaN(d)) continue;
        const daysAgo = Math.floor((now - d) / 86400000);
        if (daysAgo >= 0 && daysAgo < days) {
          buckets[days - 1 - daysAgo]++;
        }
      }
      const max = Math.max(...buckets, 1);
      return buckets.map((v) => Math.round((v / max) * 100));
    },

    totalOrchestratorRuns(): number {
      const days = 14;
      const now = Date.now();
      const cutoff = now - days * 86400000;
      let count = 0;
      for (const mission of this.agentMissions) {
        const d = new Date(mission.created_on).getTime();
        if (!isNaN(d) && d >= cutoff) count++;
      }
      for (const run of this.agentRuns) {
        const d = new Date(run.created_on || run.started_at || run.created_at).getTime();
        if (!isNaN(d) && d >= cutoff) count++;
      }
      return count;
    },

    orchestratorMissionsByStatus(): { label: string; count: number; color: string }[] {
      const counts: Record<string, number> = {};
      for (const m of this.missions) {
        const s = m.status || 'unknown';
        counts[s] = (counts[s] || 0) + 1;
      }
      const statusColors: Record<string, string> = {
        active: '#42a5f5',
        planning: '#ab47bc',
        completed: '#66bb6a',
        paused: '#ffa726',
        cancelled: '#ef5350',
        waiting_approval: '#78909c',
        failed: '#e53935',
      };
      return Object.entries(counts)
        .filter(([, count]) => count > 0)
        .map(([label, count]) => ({
          label: statusLabel(this.$t, label),
          count,
          color: statusColors[label] || '#9e9e9e',
        }));
    },

    statusData(): { label: string; count: number; color: string }[] {
      const counts: Record<string, number> = {};
      const cutoff = Date.now() - 14 * 86400000;
      for (const t of this.agentTasks) {
        const modified = new Date(t.last_modified_on || t.created_on).getTime();
        if (modified < cutoff) continue;
        const s = t.status || 'unknown';
        counts[s] = (counts[s] || 0) + 1;
      }
      const statusColors: Record<string, string> = {
        backlog: '#90a4ae',
        todo: '#2196f3',
        in_progress: '#ff9800',
        in_review: '#7c4dff',
        done: '#66bb6a',
        cancelled: '#9e9e9e',
        blocked: '#e53935',
      };
      return Object.entries(counts).map(([label, count]) => ({
        label: statusLabel(this.$t, label),
        count,
        color: statusColors[label] || '#9e9e9e',
      }));
    },
  },

  methods: {
    formatToolName,
    openEditWizard() {
      this.showEditWizard = true;
    },

    /** Per-tool *configured* gating for the read-only skill
     *  chips.  Mirrors the policy the user has set for this
     *  agent (default ``CRITICAL_TOOLS`` XOR explicit override),
     *  independent of the current ``approval_mode`` — the chip
     *  shows what the user configured, not what the runtime will
     *  do under the current mode. */
    isToolEffectivelyCritical(toolName: string): boolean {
      if (!this.profile) return false;
      const overrides =
        this.agentsSettingsStore.toolApprovalsByAgent[this.profile.agent.id] || {};
      if (toolName in overrides) return overrides[toolName] === true;
      return this.agentsSettingsStore.isCriticalTool(toolName);
    },
    openMcpEditor() {
      this.mcpEditorValue = JSON.parse(JSON.stringify(this.profile?.agent.mcp_servers || {}));
      this.disabledToolsValue = [...(this.profile?.agent.config?.disabled_tools || [])];
      // Seed from the effective tool list (``agent.tools``) so the
      // dialog renders checkmarks for every tool the agent
      // currently has, not only the explicitly-added MCP tools.
      // The McpToolSelector's ``mcp-tools`` prop feeds
      // ``explicitBuiltInTools``, which is OR'd with the
      // skill-derived active state — passing the broader set is
      // safe (skill-included tools stay marked active even if
      // someone later removes them from the explicit list).
      this.mcpToolsValue = [...(this.profile?.agent.tools || [])];
      this.toolApprovalsValue = { ...(this.profile?.agent.config?.tool_approvals || {}) };
      this.showMcpEditor = true;
    },
    async saveMcpTools() {
      if (!this.profile) return;
      // Defensive: the Save button is already hidden for system
      // agents (the dialog renders a Done button instead), and the
      // backend returns 403 for tool/skill writes on system agents
      // anyway.  This guard makes the front-end behaviour
      // self-consistent if a future change accidentally re-enables
      // the Save path for system agents.
      if (this.profile.agent.is_system) return;
      this.savingMcpTools = true;
      try {
        const mergedConfig = {
          ...this.profile.agent.config,
          disabled_tools: this.disabledToolsValue,
          tool_approvals: { ...this.toolApprovalsValue },
        };
        const updated = await agentApiService.update(this.profile.agent.id, {
          mcp_servers: this.mcpEditorValue,
          mcp_tools: this.mcpToolsValue,
          config: mergedConfig,
        });
        // Mirror the server's authoritative response back onto the
        // profile so the read-only Skills cards (which read
        // ``agent.tools``) reflect the new selection without a
        // page reload.  Using the server's value also catches any
        // backend-side normalization (e.g. always-included tools
        // re-added).
        this.profile.agent.mcp_servers = JSON.parse(
          JSON.stringify(updated.mcp_servers || this.mcpEditorValue),
        );
        this.profile.agent.mcp_tools = [...(updated.mcp_tools || this.mcpToolsValue)];
        this.profile.agent.tools = [...(updated.tools || [])];
        this.profile.agent.skills = JSON.parse(
          JSON.stringify(updated.skills || this.profile.agent.skills || []),
        );
        if (this.profile.agent.config) {
          this.profile.agent.config.disabled_tools = [...this.disabledToolsValue];
          this.profile.agent.config.tool_approvals = { ...this.toolApprovalsValue };
        }
        // Refresh the store cache so badges elsewhere reflect the
        // newly persisted overrides without a page reload.
        this.agentsSettingsStore.toolApprovalsByAgent = {
          ...this.agentsSettingsStore.toolApprovalsByAgent,
          [this.profile.agent.id]: { ...this.toolApprovalsValue },
        };
        this.showMcpEditor = false;
        notify.success(this.$t('docnet_tools_updated'));
      } catch (err: any) {
        notify.error(err?.message || this.$t('docnet_tools_save_failed'));
      } finally {
        this.savingMcpTools = false;
      }
    },

    async savePrompt(): Promise<void> {
      if (!this.profile) return;
      this.savingPrompt = true;
      try {
        const { default: AgentApiService } = await import('src/services/settings/AgentApiService');
        const apiService = new AgentApiService();
        await apiService.update(this.profile.agent.id, { system_prompt: this.promptDraft });
        this.profile.agent.system_prompt = this.promptDraft;
        this.editingPrompt = false;
        notify.success(this.$t('docnet_prompt_updated'));
      } catch {
        notify.error(this.$t('docnet_prompt_update_failed'));
      } finally {
        this.savingPrompt = false;
      }
    },

    async updateConfigField(field: string, value: any): Promise<void> {
      if (!this.profile) return;
      try {
        const currentConfig = this.profile.agent.config || {};
        const updatedConfig = { ...currentConfig, [field]: value };
        const { default: AgentProfileService } = await import('src/services/docnet/DocNetAgentProfileService');
        const svc = new AgentProfileService();
        await svc.updateAgentConfig(this.profile.agent.id, updatedConfig);
        if (this.profile.agent.config) {
          (this.profile.agent.config as any)[field] = value;
        }
      } catch {
        notify.error(this.$t('docnet_setting_update_failed'));
      }
    },

    async updateReasoningEffort(value: string): Promise<void> {
      if (!this.profile) return;
      try {
        // Dedicated endpoint — routes to agent_org_settings for system agents
        // (like approval mode / custom instructions), so this works for system
        // agents instead of 403-ing on the generic config update.
        await agentApiService.updateReasoningEffort(this.profile.agent.id, value);
        if (this.profile.agent.config) {
          (this.profile.agent.config as any).reasoning_effort = value;
        }
        notify.success(this.$t('MSG_SAVE'));
      } catch {
        notify.error(this.$t('docnet_reasoning_effort_update_failed'));
      }
    },

    async onAgentEdited() {
      this.showEditWizard = false;
      await this.agentStore.fetchProfiles(true);
      notify.success(this.$t('docnet_agent_updated'));
    },

    async deleteAgent() {
      if (!this.profile) return;
      this.deleting = true;
      try {
        await agentApiService.deleteAgent(this.profile.agent.id);
        notify.success(this.$t('docnet_agent_deleted'));
        this.showDeleteConfirm = false;
        this.router.push('/doc-net/agents');
      } catch (err: any) {
        notify.error(err?.response?.data?.detail || this.$t('docnet_agent_delete_failed'));
      } finally {
        this.deleting = false;
      }
    },

    isAgentAssigned(agentId: string): boolean {
      if (!this.profile) return false;
      const p = this.profiles.find((pr) => pr.agent.id === agentId);
      if (!p) return false;
      const rt = p.reports_to;
      if (Array.isArray(rt)) return rt.includes(this.profile.agent.id);
      return rt === this.profile.agent.id;
    },

    async toggleAgentAssignment(agentId: string, assigned: boolean): Promise<void> {
      if (!this.profile) return;
      const orchId = this.profile.agent.id;
      const p = this.profiles.find((pr) => pr.agent.id === agentId);
      const current = p?.reports_to;

      let newReportsTo: string[] | null;
      if (assigned) {
        // Add this orchestrator to the list
        const existing = Array.isArray(current) ? current : (current ? [current] : []);
        newReportsTo = [...new Set([...existing, orchId])];
      } else {
        // Remove this orchestrator from the list
        const existing = Array.isArray(current) ? current : (current ? [current] : []);
        newReportsTo = existing.filter((id: string) => id !== orchId);
        if (newReportsTo.length === 0) newReportsTo = null;
      }
      try {
        await this.agentStore.updateAgentReportsTo(agentId, newReportsTo);
        notify.success(this.$t('MSG_SAVE'));
      } catch {
        notify.error(this.$t('agent_toggle_failed'));
      }
    },

    shortId(id: string): string {
      return id ? id.slice(0, 8) : '—';
    },

    formatDuration(ms: number): string {
      const secs = Math.round(ms / 1000);
      if (secs < 60) return `${secs}s`;
      return `${Math.floor(secs / 60)}m ${secs % 60}s`;
    },

    missionTokens(m: DocNetMission): string {
      if (!m.token_usage) return '';
      const total = m.token_usage.billed ?? 0;
      if (!total) return '';
      return total.toLocaleString();
    },

    relativeTime(dateStr: string): string {
      return formatRelativeTime(dateStr, this.$t);
    },

    runStatusColor(status: string): string {
      const map: Record<string, string> = {
        completed: 'positive',
        success: 'positive',
        running: 'info',
        failed: 'negative',
        cancelled: 'grey-6',
      };
      return map[status] || 'grey-6';
    },

    renderMarkdown,

    async togglePersonality(key: string): Promise<void> {
      if (!this.profile) return;
      const newVal = this.selectedPersonality === key ? null : key;
      this.savingPersonality = key;
      try {
        const svc = new AgentApiService();
        const result = await svc.updatePersonality(this.profile.agent.id, newVal);
        this.selectedPersonality = result.personality;
        notify.success(
          result.personality
            ? this.$t('personality_saved') as string
            : this.$t('personality_cleared') as string,
        );
      } catch {
        notify.error(this.$t('personality_save_failed') as string);
      } finally {
        this.savingPersonality = null;
      }
    },

    startEditInstructions() {
      // Pre-fill the textarea with the current effective value —
      // the org's overlay if they have one, the inherited default
      // otherwise.  The "freeze on default" trap (admin saves the
      // inherited text verbatim and locks the org onto the current
      // default forever) is prevented by ``instructionsChanged``
      // disabling the Save button until the draft actually differs
      // from the inherited value.  No need for a separate "Start
      // from inherited" button — the textarea opens with the right
      // starting point either way.
      this.instructionsDraft = this.customInstructions;
      this.editingInstructions = true;
    },

    cancelEditInstructions() {
      this.editingInstructions = false;
      this.instructionsDraft = '';
    },

    async saveInstructions(): Promise<void> {
      if (!this.profile || !this.instructionsChanged) return;
      this.savingInstructions = true;
      try {
        const agentApiService = new AgentApiService();
        const result = await agentApiService.updateCustomInstructions(this.profile.agent.id, this.instructionsDraft.trim());
        this.loadedCustomInstructions = result.custom_instructions || '';
        // PUT mirrors GET's effective-state semantics: clearing on a
        // system agent that has a base default flips ``is_default``
        // back to true, so we always trust the response rather than
        // assuming the just-saved value is the org's own.
        this.loadedIsDefault = result.is_default ?? false;
        this.editingInstructions = false;
        notify.success(this.loadedCustomInstructions ? this.$t('docnet_custom_instructions_saved') : this.$t('docnet_custom_instructions_cleared'));
      } catch {
        notify.error(this.$t('docnet_custom_instructions_save_failed'));
      } finally {
        this.savingInstructions = false;
      }
    },

    async onApprovalModeChange(mode: string): Promise<void> {
      if (!this.profile) return;
      this.savingApproval = true;
      try {
        const AgentApiService = (await import('src/services/settings/AgentApiService')).default;
        const svc = new AgentApiService();
        await svc.updateApprovalMode(this.profile.agent.id, mode);
        this.profile.approval_mode = mode;
        notify.success(this.$t('approval_mode_saved'));
      } catch {
        notify.error(this.$t('approval_toggle_failed'));
      } finally {
        this.savingApproval = false;
      }
    },

    async toggleEnabled(enabled: boolean): Promise<void> {
      if (!this.profile) return;
      this.toggleLoading = true;
      try {
        const { useUserStore } = await import('src/store/User/user_details.store');
        const userId = useUserStore().getUserId() as string;
        const agentApiService = new (await import('src/services/settings/AgentApiService')).default();
        await agentApiService.toggle(this.profile.agent.id, enabled, userId);
        this.profile.agent.is_enabled = enabled;
        notify.success(this.$t('MSG_SAVE'));
      } catch {
        notify.error(this.$t('agent_toggle_failed'));
      } finally {
        this.toggleLoading = false;
      }
    },
  },

  async mounted() {
    const id = this.$route.params.id as string;
    if (!id || id === 'null' || id === 'undefined') {
      this.router.replace('/doc-net/agents');
      return;
    }
    await Promise.allSettled([
      this.agentStore.fetchProfile(id),
      this.agentStore.fetchProfiles(),
      this.agentStore.fetchAgentRuns(id),
      this.taskStore.fetchIssues(),
      this.missionStore.fetchMissions(),
      this.agentsSettingsStore.fetchMcpServerNames(),
      // Skill → tools mapping comes from GET /agents/skills; needed so
      // the "Advanced tool settings" dialog renders the full built-in
      // tool groups and not just the always-available request_human_approval.
      this.agentsSettingsStore.fetchSkills(),
      // Tool-classification metadata (which tools are flagged
      // ``critical``).  Drives the warning indicator on tool
      // chips so admins can see at a glance which tools will
      // require human approval at runtime.
      this.agentsSettingsStore.fetchToolMetadata(),
      // Per-agent ``tool_approvals`` overrides — needed so the
      // skill cards' tool chips reflect the agent's actual
      // configured policy (e.g. a non-critical tool the user
      // pinned to "always require approval"), not just the
      // global default.
      this.agentsSettingsStore.fetchToolApprovals(id),
    ]);

    // Load custom instructions and personality from org settings
    try {
      const AgentApiService = (await import('src/services/settings/AgentApiService')).default;
      const agentApiService = new AgentApiService();
      const [instrResult, persResult, approvalResult] = await Promise.allSettled([
        agentApiService.getCustomInstructions(id),
        agentApiService.getPersonality(id),
        agentApiService.getApprovalMode(id),
      ]);
      if (instrResult.status === 'fulfilled') {
        this.loadedCustomInstructions = instrResult.value.custom_instructions || '';
        this.loadedIsDefault = instrResult.value.is_default ?? false;
        // Auto-open when there is content to show — covers both the
        // inherited-default and org-overlay cases.  Empty Custom
        // Instructions on a custom agent stay collapsed so the
        // section doesn't introduce empty noise on the profile.
        // Without this, the inherited default + its "inherited"
        // badge would be hidden behind a click, defeating the UX.
        if (this.loadedCustomInstructions) {
          this.showCustomInstructions = true;
        }
      }
      if (persResult.status === 'fulfilled') {
        this.selectedPersonality = persResult.value.personality;
      }
      if (approvalResult.status === 'fulfilled' && this.profile) {
        this.profile.approval_mode = approvalResult.value.approval_mode;
      }
    } catch {
      // Endpoints not available
    }

    // Subscribe to agents channel for status updates
    const orgId = getOrgId();
    if (orgId) {
      useDocNetWebSocketStore().subscribe(`agents:${orgId}`);
    }
  },

  beforeUnmount() {
    const orgId = getOrgId();
    if (orgId) {
      useDocNetWebSocketStore().unsubscribe(`agents:${orgId}`);
    }
  },
});
</script>

