import DocNetBaseService from 'src/services/docnet/DocNetBaseService';
import { api } from 'src/pages/APIs';

export type AgentMemorySource =
  | 'user_feedback'
  | 'self_reflection'
  | 'episodic';

export interface AgentMemory {
  id: string;
  org_id: string;
  agent_id: string | null;
  source: AgentMemorySource;
  content: string;
  context: Record<string, unknown>;
  tags: string[];
  confidence: number;
  usage_count: number;
  helpful_count: number;
  unhelpful_count: number;
  source_run_id: string | null;
  superseded_by_id: string | null;
  created_at: string;
  updated_at: string;
}

export interface AgentMemoryList {
  total: number;
  items: AgentMemory[];
}

export interface AgentMemoryStats {
  agent_id: string | null;
  total: number;
  by_source: Record<string, number>;
  total_applied: number;
  helpful: number;
  unhelpful: number;
}

export interface ListMemoriesParams {
  agent_id?: string | null;
  source?: AgentMemorySource | null;
  limit?: number;
  offset?: number;
}

/**
 * Client for the DocNet Agent Memory & Learning system.
 *
 * Backed by the backend routes mounted under ``/api/v2/agent-memories``
 * and ``/api/v2/agent-runs/{run_id}/feedback``. The base service
 * handles auth + org-id injection so org-scope is enforced server-side.
 */
export default class DocNetAgentMemoryService extends DocNetBaseService {
  public async list(params: ListMemoriesParams = {}): Promise<AgentMemoryList> {
    const headers = await this.getHeaders();
    const query: string[] = [];
    if (params.agent_id) query.push(`agent_id=${encodeURIComponent(params.agent_id)}`);
    if (params.source) query.push(`source=${encodeURIComponent(params.source)}`);
    if (params.limit != null) query.push(`limit=${params.limit}`);
    if (params.offset != null) query.push(`offset=${params.offset}`);
    const url = query.length
      ? `${api.docnet_agent_memories}?${query.join('&')}`
      : api.docnet_agent_memories;
    return (await super.get(url, { headers })) as AgentMemoryList;
  }

  public async stats(agentId?: string | null): Promise<AgentMemoryStats> {
    const headers = await this.getHeaders();
    const url = agentId
      ? `${api.docnet_agent_memory_stats}?agent_id=${encodeURIComponent(agentId)}`
      : api.docnet_agent_memory_stats;
    return (await super.get(url, { headers })) as AgentMemoryStats;
  }

  public async feedback(
    memoryId: string,
    verdict: 'helpful' | 'unhelpful',
  ): Promise<AgentMemory> {
    const headers = await this.getHeaders();
    return (await super.post(
      `${api.docnet_agent_memories}/${memoryId}/feedback`,
      { verdict },
      { headers },
    )) as AgentMemory;
  }

  public async remove(memoryId: string): Promise<{ success: boolean; id: string }> {
    const headers = await this.getHeaders();
    // AbstractApiService.delete signature is (path, payload, config?).
    // Pass an empty payload object so headers land in the config slot
    // — otherwise the Authorization header gets nested inside the
    // payload and is never attached to the request, returning 401.
    return (await super.delete(
      `${api.docnet_agent_memories}/${memoryId}`,
      {},
      { headers },
    )) as { success: boolean; id: string };
  }

  public async submitRunFeedback(
    runId: string,
    payload: {
      verdict: 'approve' | 'reject' | 'correct';
      lesson?: string;
      notes?: string;
      tags?: string[];
    },
  ): Promise<AgentMemoryList> {
    const headers = await this.getHeaders();
    return (await super.post(
      `${api.docnet_agent_run_feedback}${runId}/feedback`,
      payload,
      { headers },
    )) as AgentMemoryList;
  }
}
